import sys
import xml.etree.ElementTree as ET
from collections import OrderedDict

def parse_xml_to_json(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except (ET.ParseError, IOError):
        sys.exit(1)

    def parse_element(element):
        result = OrderedDict()
        for child in element:
            child_data = parse_element(child)
            if child.tag in result:
                if isinstance(result[child.tag], list):
                    result[child.tag].append(child_data)
                else:
                    result[child.tag] = [result[child.tag], child_data]
            else:
                result[child.tag] = child_data
        return result

    def get_value(element):
        value_attr = element.get('value')
        if value_attr is not None:
            return value_attr
        enabled_attr = element.get('enabled')
        if enabled_attr is not None:
            return enabled_attr.lower() == 'true'
        text = element.text
        if text is not None:
            return text.strip()
        return False

    children = []
    for child in root:
        children.append(get_value(child))

    json_data = OrderedDict()
    for child in root:
        child_data = parse_element(child)
        if child_data:
            json_data[child.tag] = child_data

    return json_data

def main():
    if len(sys.argv) != 2:
        sys.exit(1)
    xml_file = sys.argv[1]
    json_data = parse_xml_to_json(xml_file)
    import json
    print(json.dumps(json_data, indent=2))

if __name__ == "__main__":
    main()

