            return None

        result = {}
        for child in root:
            if child.tag not in result:
                attr = child.get('value')
                if attr is not None:
                    result[child.tag] = attr
                else:
                    text = child.text.strip() if child.text else ''
                    result[child.tag] = text
        return result
    except (IOError, ET.ParseError):
        return None

def main():
