import sys
import json
import xml.etree.ElementTree as ET

def xml_to_json(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        if root.tag != 'configuration':
            return None
        json_obj = {}
        for child in root:
            key = child.tag
            value = child.attrib.get('value', child.text.strip() if child.text else '')
            json_obj[key] = value
        return json_obj
    except (ET.ParseError, FileNotFoundError):
        return None

if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(1)
    xml_file = sys.argv[1]
    json_obj = xml_to_json(xml_file)
    if json_obj is None:
        sys.exit(1)
    print(json.dumps(json_obj, indent=2))
    sys.exit(0)
